#!/usr/bin/env python3
"""Exercise link eligibility for content changes and changed native inputs."""
import copy, hashlib, importlib.util, json, tempfile
from pathlib import Path

spec=importlib.util.spec_from_file_location('linkkit',Path(__file__).with_name('ios-link-kit.py'))
kit=importlib.util.module_from_spec(spec); spec.loader.exec_module(kit)
sha=lambda b: hashlib.sha256(b).hexdigest()

def sample(base, app_id, header, plan, hbc):
    app=base/'app'; bake=base/'bake'; bake.mkdir(parents=True)
    cargo=app/'.exact/shells/Cargo.toml'; cargo.parent.mkdir(parents=True)
    cargo.write_bytes(('# '+header+"'s native workspace, generated by exact2 from app.json and the app's own crates (LLP 1153 D1,\n[workspace]\n").encode())
    for n in kit.COMPILED: (bake/n).write_bytes(n.encode())
    (bake/'app.plan').write_bytes(plan); (bake/'app.hbc').write_bytes(hbc)
    compat={'id':app_id,'target':'aarch64-apple-ios','inputs':{'app':app_id,'platform':'ios','keys':{'a':app_id},'typescriptModule':sha(hbc),'linked':['router']},'embedded':{'trust':'production','plan':{'sha256':sha(plan)}}}
    (bake/'compat.json').write_text(json.dumps(compat))
    receipt={'trust':'production','compat':compat,'products':[{'path':'lib.a','sha256':'a'*64}], 'binary':{'configuration':{'target':'ios','units':[]},'metadata':{'app':app_id,'host':{'minimumOS':'17.0'}},'sourceInputs':{'files':[{'root':'app','path':'.exact/shells/Cargo.toml','sha256':sha(cargo.read_bytes())}]}},'graph':{'artifacts':[{'name':'app.plan','bytes':len(plan),'sha256':sha(plan),'requires':{'app':app_id,'appleUses':['router']}}]}}
    receipt_path=base/'receipt.json';receipt_path.write_text(json.dumps(receipt))
    return receipt,receipt_path,bake,app

with tempfile.TemporaryDirectory() as tmp:
    root=Path(tmp); a,ar,ab,aa=sample(root/'a','dev.test.a','First',b'first plan',b'first bytecode'); b,br,bb,ba=sample(root/'b','dev.test.b','Second',b'second plan',b'second bytecode')
    baseline=kit.facts(ar,ab,aa)
    assert baseline==kit.facts(br,bb,ba), 'content and identity should not change native eligibility'
    first=copy.deepcopy(baseline); second=copy.deepcopy(baseline)
    first['compat']['grantCeiling']='net.websocket wss://first.invalid'
    second['compat']['grantCeiling']='net.websocket wss://second.invalid'
    assert kit.runtime_grants(first)==kit.runtime_grants(second), 'runtime grants should come from the new compat section'
    second['compat']['linked']=['router','notifications']
    assert kit.runtime_grants(first)!=kit.runtime_grants(second), 'native capability changes must invalidate kit'
    for bad in ('net.fetch https://example.invalid', 'net.websocket ws://insecure.invalid',
                'net.websocket wss://first.invalid\nfs.read app:/',
                'net.websocket wss://one.invalid\nnet.websocket wss://two.invalid', ''):
        invalid=copy.deepcopy(first); invalid['compat']['grantCeiling']=bad
        try: kit.runtime_grants(invalid)
        except ValueError: pass
        else: raise AssertionError('unsupported grant was accepted: '+repr(bad))
    different=copy.deepcopy(first); different['compat']['javascriptGrants']='net.websocket wss://other.invalid'
    try: kit.runtime_grants(different)
    except ValueError: pass
    else: raise AssertionError('inconsistent origins were accepted')
    b['binary']['configuration']['target']='different-target';br.write_text(json.dumps(b))
    assert baseline!=kit.facts(br,bb,ba), 'compiler configuration must invalidate kit'
    (ba/'.exact/shells/Cargo.toml').write_text('tampered')
    try: kit.facts(br,bb,ba)
    except ValueError as e: assert 'does not match receipt' in str(e)
    else: raise AssertionError('unrecorded Cargo manifest change was accepted')
print('link kit eligibility smoke passed')
